import { useMemo, useState, type FormEvent } from "react";

type Service = {
  id: string;
  name: string;
  price: number;
  description: string;
};

const SERVICES: Service[] = [
  {
    id: "classic",
    name: "Classic Cut",
    price: 28,
    description: "Scissor and clipper cut with a clean finish.",
  },
  {
    id: "beard",
    name: "Beard Trim",
    price: 15,
    description: "Shape, line-up, and hot towel treatment.",
  },
  {
    id: "full",
    name: "Cut + Beard",
    price: 40,
    description: "The full service — haircut and beard detail.",
  },
];

export default function AppointmentForm() {
  const [selectedService, setSelectedService] = useState<string>(SERVICES[0]?.id ?? "");
  const [date, setDate] = useState("");
  const [name, setName] = useState("");
  const [errors, setErrors] = useState<{ date?: string; name?: string }>({});
  const [confirmation, setConfirmation] = useState<string | null>(null);

  const today = useMemo(() => new Date().toISOString().split("T")[0], []);

  const selected = SERVICES.find((s) => s.id === selectedService);

  function validate(): boolean {
    const next: { date?: string; name?: string } = {};

    if (!name.trim()) {
      next.name = "Please enter your name.";
    } else if (name.trim().length < 2) {
      next.name = "Name must be at least 2 characters.";
    }

    if (!date) {
      next.date = "Please choose a date.";
    } else if (date < today) {
      next.date = "Please choose today or a future date.";
    }

    setErrors(next);
    return Object.keys(next).length === 0;
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setConfirmation(null);
    if (!validate()) return;

    const formatted = new Date(`${date}T00:00:00`).toLocaleDateString(undefined, {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    });

    setConfirmation(
      `Thanks, ${name.trim()}! Your ${selected?.name ?? "appointment"} request for ${formatted} has been noted.`
    );
    setName("");
    setDate("");
    setSelectedService(SERVICES[0]?.id ?? "");
  }

  return (
    <div className="card">
      <header className="card__header">
        <h1>Cedar Cuts</h1>
        <p>Book your next appointment with us.</p>
      </header>

      <form onSubmit={handleSubmit} noValidate>
        <fieldset className="fieldset">
          <legend>Choose a service</legend>
          <div className="services">
            {SERVICES.map((service) => (
              <label
                key={service.id}
                className={`service ${selectedService === service.id ? "service--selected" : ""}`}
              >
                <input
                  type="radio"
                  name="service"
                  value={service.id}
                  checked={selectedService === service.id}
                  onChange={() => setSelectedService(service.id)}
                />
                <span className="service__info">
                  <span className="service__name">{service.name}</span>
                  <span className="service__desc">{service.description}</span>
                </span>
                <span className="service__price">${service.price}</span>
              </label>
            ))}
          </div>
        </fieldset>

        <label className="field">
          <span className="field__label">Your name</span>
          <input
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. Sam Rivera"
            aria-invalid={Boolean(errors.name)}
            aria-describedby={errors.name ? "name-error" : undefined}
          />
          {errors.name && (
            <span className="field__error" id="name-error" role="alert">
              {errors.name}
            </span>
          )}
        </label>

        <label className="field">
          <span className="field__label">Preferred date</span>
          <input
            type="date"
            value={date}
            min={today}
            onChange={(e) => setDate(e.target.value)}
            aria-invalid={Boolean(errors.date)}
            aria-describedby={errors.date ? "date-error" : undefined}
          />
          {errors.date && (
            <span className="field__error" id="date-error" role="alert">
              {errors.date}
            </span>
          )}
        </label>

        <button type="submit" className="submit">
          Request appointment
        </button>
      </form>

      {confirmation && (
        <div className="confirmation" role="status">
          {confirmation}
        </div>
      )}

      <p className="notice">
        This is a frontend demo — requests are not sent or saved online.
      </p>
    </div>
  );
}

