* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #f5efe4;
  color: #26301f;
  font: 16px/1.6 system-ui, -apple-system, "Segoe UI", sans-serif;
  -webkit-font-smoothing: antialiased;
}

button,
input {
  font: inherit;
}

/* Page shell */
.page {
  min-height: 100vh;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 40px 16px;
  background: radial-gradient(
      1200px 600px at 50% -10%,
      rgba(255, 255, 255, 0.55),
      transparent 60%
    ),
    #f5efe4;
}

/* Card */
.card {
  width: 100%;
  max-width: 560px;
  background: #fffdf7;
  border: 1px solid #e4dcc9;
  border-radius: 20px;
  padding: 32px;
  box-shadow: 0 18px 40px rgba(60, 74, 44, 0.12);
}

.card__header {
  margin-bottom: 28px;
}

.card__header h1 {
  margin: 0 0 6px;
  font-size: clamp(28px, 5vw, 36px);
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: #1f2b18;
}

.card__header p {
  margin: 0;
  color: #6b7a5c;
}

/* Services */
.fieldset {
  border: none;
  margin: 0 0 24px;
  padding: 0;
}

.fieldset legend {
  display: block;
  width: 100%;
  margin-bottom: 12px;
  font-weight: 600;
  color: #1f2b18;
}

.services {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.service {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px;
  background: #fbf8ef;
  border: 2px solid #e6decc;
  border-radius: 14px;
  cursor: pointer;
  transition:
    border-color 0.15s ease,
    background-color 0.15s ease,
    box-shadow 0.15s ease;
}

.service:hover {
  border-color: #b9c6a2;
  background: #f7f3e6;
}

.service input[type="radio"] {
  flex: 0 0 auto;
  width: 18px;
  height: 18px;
  accent-color: #3f5a2f;
  cursor: pointer;
}

.service__info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.service__name {
  font-weight: 600;
  color: #1f2b18;
}

.service__desc {
  color: #6b7a5c;
  font-size: 0.9rem;
}

.service__price {
  margin-left: auto;
  font-weight: 700;
  color: #3f5a2f;
  white-space: nowrap;
}

.service--selected {
  background: #eef1e0;
  border-color: #3f5a2f;
  box-shadow: 0 0 0 3px rgba(63, 90, 47, 0.15);
}

/* Fields */
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 18px;
}

.field__label {
  font-weight: 600;
  color: #1f2b18;
}

.field input {
  width: 100%;
  padding: 12px 14px;
  background: #fff;
  border: 2px solid #d8cfba;
  border-radius: 10px;
  color: #26301f;
  transition: border-color 0.15s ease;
}

.field input:focus {
  outline: none;
  border-color: #3f5a2f;
  box-shadow: 0 0 0 3px rgba(63, 90, 47, 0.2);
}

.field input[aria-invalid="true"] {
  border-color: #b3402f;
}

.field__error {
  color: #b3402f;
  font-size: 0.85rem;
  font-weight: 500;
}

/* Submit */
.submit {
  width: 100%;
  padding: 14px 20px;
  background: #3f5a2f;
  color: #fffdf7;
  border: none;
  border-radius: 12px;
  font-weight: 600;
  font-size: 1.05rem;
  cursor: pointer;
  transition: background-color 0.15s ease;
}

.submit:hover {
  background: #354b28;
}

.submit:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px #f5efe4, 0 0 0 6px #3f5a2f;
}

.submit:active {
  background: #2c3f21;
}

/* Confirmation */
.confirmation {
  margin-top: 20px;
  padding: 14px 16px;
  background: #eef1e0;
  border: 1px solid #b9c6a2;
  border-radius: 10px;
  color: #2c3f21;
  font-weight: 500;
}

/* Notice */
.notice {
  margin: 18px 0 0;
  color: #8a8f7e;
  font-size: 0.85rem;
  text-align: center;
}

/* Responsive: mobile single-column */
@media (max-width: 420px) {
  .page {
    padding: 16px 12px;
  }

  .card {
    padding: 24px 18px;
    border-radius: 16px;
  }

  .service {
    padding: 14px;
  }
}

/* Visible keyboard focus for interactive elements */
.service:focus-within {
  border-color: #3f5a2f;
  box-shadow: 0 0 0 3px rgba(63, 90, 47, 0.2);
}
